 [STAThread]static void Main(string[] a){dir=Path.GetFullPath(a[0]);Directory.CreateDirectory(dir);try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Pure();Ui();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+assertions+" assertions: text/symbol/EAN/GS1 duplication, independent data, XML/Word/PDF/SVG/ZPL round trip, clipboard validation and ordinary text focus, header actions, localized tooltips/accessibility, themes and simulated 100/150/200% geometry. System clipboard routing, native file dialogs, real monitor DPI and high contrast need manual checks.");}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
 static void Pure(){var s=LabelSettings.Default();s.Texts.Clear();s.BarX=10.123;s.BarY=9.75;var copy=new SymbolItem{Code=BarcodeContent.From(s),X=s.BarX,Y=s.BarY,Width=s.BarWidth,Height=Engine.BarcodeHeight(s)};using(var original=VectorArt.Build(s)){s.Symbols.Add(copy);using(var scene=VectorArt.Build(s)){int n=0;foreach(var shape in scene.Shapes)if(shape.Element==-3){var expected=original.Shapes[n++].Path.PathPoints;var actual=shape.Path.PathPoints;Check(actual.Length==expected.Length,"barcode path point count");double difference=0;for(int q=0;q<actual.Length;q++)difference=Math.Max(difference,Math.Max(Math.Abs(actual[q].X-expected[q].X),Math.Abs(actual[q].Y-expected[q].Y)));File.AppendAllText(Path.Combine(dir,"vector-difference-mm.txt"),difference+"\r\n");Check(difference<.0001,"barcode geometry preserved at original size: "+difference);}Check(n==original.Shapes.Count,"all barcode shapes copied");}}copy.Code.Ean="4006381333931";var clone=copy.Copy();clone.Code.Ean="8580000000016";Check(copy.Code.Ean!=clone.Code.Ean,"deep code clone");foreach(string bad in new[]{"<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///c:/bad'>]><ElementTransfer/>","<ElementTransfer/>",new string('x',200001)}){bool rejected=false;try{ElementTransfer.Decode(bad);}catch{rejected=true;}Check(rejected,"reject invalid clipboard");}}
 static void Ui(){using(var f=new MainForm(Path.Combine(dir,"preferences.xml"))){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();var p=Field<PreviewPanel>(f,"preview");var baseLabel=LabelSettings.Default();baseLabel.Symbols.Add(new SymbolItem());Call(f,"Apply",baseLabel);p.Focus();p.SelectElement(0);Key(f,Keys.Control|Keys.C);Key(f,Keys.Control|Keys.V);var s=(LabelSettings)Call(f,"Read");Check(s.Texts.Count==2&&p.SelectedIndex==1,"copy/paste core selects new item");Check(s.Texts[1].Text==s.Texts[0].Text&&s.Texts[1].FontName==s.Texts[0].FontName&&s.Texts[1].X==s.Texts[0].X+2,"preserve text/style with 2mm offset");Key(f,Keys.Control|Keys.V);s=(LabelSettings)Call(f,"Read");Check(s.Texts.Count==3&&s.Texts[2].X==s.Texts[0].X+4,"repeated paste offset");p.SelectElement(-3);Key(f,Keys.Control|Keys.C);Key(f,Keys.Control|Keys.V);Check(((LabelSettings)Call(f,"Read")).Symbols.Count==2,"deposit duplicate");p.SelectElement(-1);Key(f,Keys.Control|Keys.C);Key(f,Keys.Control|Keys.V);s=(LabelSettings)Call(f,"Read");Check(s.Symbols.Count==3&&s.Symbols[2].Code.Kind==13,"EAN duplicate");Check(s.Symbols[2].Width==s.BarWidth&&s.Symbols[2].Height==Engine.BarcodeHeight(s),"barcode physical size");s.Kind=128;s.Gs1Mode=true;s.BarWidth=50;s.ApplicationIdentifiers.Add(new AiValue{AI="10",Data="LOT123"});Call(f,"Apply",s);p.Focus();p.SelectElement(-1);Key(f,Keys.Control|Keys.C);Key(f,Keys.Control|Keys.V);s=(LabelSettings)Call(f,"Read");Check(s.Symbols[3].Code.Gs1Mode&&s.Symbols[3].Code.ApplicationIdentifiers[0].Data=="LOT123","GS1 duplicate");s.ApplicationIdentifiers[0].Data="CHANGED";Check(s.Symbols[3].Code.ApplicationIdentifiers[0].Data=="LOT123","GS1 deep data");Call(f,"Apply",s);p.SelectElement(-6);p.Focus();Key(f,Keys.Control|Keys.C);Key(f,Keys.Control|Keys.V);s=(LabelSettings)Call(f,"Read");Check(s.Symbols.Count==5&&s.Symbols[4].Code.Gs1Mode,"copy copied code");
 string project=Path.Combine(dir,"copies.ean.xml");Set(f,"settingsPath",project);Key(f,Keys.Control|Keys.S);Check(File.Exists(project)&&!Field<bool>(f,"dirty"),"CtrlS actual save");var loaded=Engine.Load(project);Check(loaded.Symbols.Count==5&&loaded.Symbols[4].Code.ApplicationIdentifiers[0].Data=="LOT123","saved code data");Engine.Pdf(Path.Combine(dir,"copies.pdf"),loaded);Engine.Docx(Path.Combine(dir,"copies.docx"),loaded);Engine.Svg(Path.Combine(dir,"copies.svg"),loaded);Engine.Zpl(Path.Combine(dir,"copies.zpl"),loaded);Check(WordParts.Create(loaded).Count==loaded.Texts.Count+loaded.Symbols.Count+1,"separate Word objects");Call(f,"OpenImportedFile",project);Check(((LabelSettings)Call(f,"Read")).Symbols.Count==5,"open actual saved document");
 Call(f,"Apply",LabelSettings.Default());var edit=Field<TextBox>(f,"ean");p.SelectElement(-1);f.ActiveControl=edit;edit.Focus();Check((bool)Call(f,"EditingText"),"text fields retain native clipboard shortcuts");var grid=Field<DataGridView>(f,"grid");Field<SplitContainer>(f,"tableSplit").Panel2Collapsed=false;grid.CurrentCell=grid.Rows[0].Cells[0];f.ActiveControl=grid;grid.Focus();grid.BeginEdit(true);Check((bool)Call(f,"EditingText"),"grid edit retains clipboard");grid.EndEdit();Field<SplitContainer>(f,"tableSplit").Panel2Collapsed=true;
 var buttons=new List<HeaderActionButton>();Control signature=null;foreach(var c in All(f)){if(c is HeaderActionButton&&((HeaderActionButton)c).Icon<=HeaderIcon.Print)buttons.Add((HeaderActionButton)c);if(c.Name=="AuthorSignature")signature=c;}Check(buttons.Count==4,"three icons and print");Check(signature!=null&&signature.Text=="Created by Daniel Návojský (ndxnraw) using Codex | 2026","signature exact");var tips=Field<UiToolTip>(f,"headerTips");Check(tips.InitialDelay==400,"tooltip delay");foreach(string language in Loc.Codes){Loc.Language=language;Call(f,"Localize");for(int i=0;i<buttons.Count;i++){var b=buttons[i];Check(b.AccessibleRole==AccessibleRole.PushButton&&!string.IsNullOrEmpty(b.AccessibleName),"accessible name");Check(tips.GetToolTip(b).Contains(i==0?"Ctrl+O":i==1?"Ctrl+S":i==2?"Ctrl+Shift+S":"Ctrl+P"),"real shortcut tooltip");Check(tips.GetToolTip(b).StartsWith(Loc.T(new[]{"Otvoriť","Uložiť","Uložiť ako","Tlačiť"}[i])),"localized tooltip");Check(b.Text=="","icon-only presentation");Check(b.Width>=36&&b.Height>=36&&b.TabStop,"hit target and tab");}}
 Loc.Language="sk";Call(f,"Localize");Call(f,"Apply",LabelSettings.Default());foreach(bool dark in new[]{true,false}){Set(f,"dark",dark);Call(f,"ApplyTheme");f.Size=new Size(1024,640);Snap(f,dark?"editor-dark-minimum":"editor-light-minimum");Check(signature.Right<=signature.Parent.ClientSize.Width&&signature.Width>=TextRenderer.MeasureText(signature.Text,signature.Font).Width-5,"signature visible at minimum");f.Size=new Size(1440,900);Snap(f,dark?"editor-dark":"editor-light");}
 // Simulated logical scaling is separate from an actual Windows monitor DPI change.
 using(var sample=new Form{Font=UiFonts.Default,StartPosition=FormStartPosition.Manual,Location=new Point(-20000,-20000)}){var row=new FlowLayoutPanel{Dock=DockStyle.Fill};sample.Controls.Add(row);foreach(int scale in new[]{100,150,200})foreach(bool dark in new[]{true,false}){row.Controls.Clear();sample.ClientSize=new Size(500*scale/100,100*scale/100);sample.BackColor=row.BackColor=StudioTheme.Bg(dark);foreach(HeaderIcon icon in new[]{HeaderIcon.Open,HeaderIcon.Save,HeaderIcon.SaveAs,HeaderIcon.Print}){var b=new HeaderActionButton(icon){Font=UiFonts.Get(10*scale/100f,System.Drawing.FontStyle.Regular),Text=icon==HeaderIcon.Print?"Tlačiť":"",BackColor=StudioTheme.Panel(dark),ForeColor=StudioTheme.Text(dark)};row.Controls.Add(b);b.Size=new Size((icon==HeaderIcon.Print?110:36)*scale/100,36*scale/100);b.RefreshPalette();var size=b.Size;b.Enabled=false;using(var bitmap=new Bitmap(b.Width,b.Height))b.DrawToBitmap(bitmap,b.ClientRectangle);b.Enabled=true;Check(size==b.Size,"disabled state no layout shift");}sample.Show();Snap(sample,"icons-"+scale+(dark?"-dark":"-light"));foreach(Control c in new List<Control>(Controls(row)))c.Dispose();}}
 // Native Button Enter/Space dispatch remains available; focused tooltip does not move focus.
 int clicks=0;using(var b=new HeaderActionButton(HeaderIcon.Save)){b.Click+=delegate{clicks++;};b.PerformClick();Check(clicks==1,"normal button activation");}p.Focus();buttons[0].Focus();Application.DoEvents();Check(tips.GetToolTip(buttons[0]).Contains("Ctrl+O"),"tooltip retained for reuse");Call(f,"Apply",LabelSettings.Default());f.Close();}}
